#include<limits.h>
/*@
assigns \nothing;
ensures INT_MIN <= \result < INT_MAX;
*/
int unknown();
#define N 100
#define fun mapavg
#include <assert.h>
int mapavg (int x[N])
{
  int i;
  long long ret;
  ret = 0;
  loop invariant 0 <= i <= N;
  loop invariant ret == \sum(0, i, (integer k) => k + x[k]);
  loop assigns i, ret;
  loop variant N - i;
  return ret / N;
}
int main ()
{
  int x[N];
  int temp;
  int ret;
  int ret2;
  int ret5;
  /*@
  loop invariant 0 <= i <= N;
  loop invariant \forall integer j; 0 <= j < i ==> (INT_MIN <= x[j] <= INT_MAX);
  loop assigns i, x[0..N-1];
  loop variant N - i;
  */
  for (int i = 0; i < N; i++) {
    x[i] = unknown();
  }
  ret = fun(x);
  temp=x[0];x[0] = x[1]; x[1] = temp;
  ret2 = fun(x);
  temp=x[0];
  /*@
  loop invariant 0 <= i <= N-1;
  loop invariant \forall integer j; 0 <= j < i ==> x[j] == \old(x[j+1]);
  loop invariant x[N-1] == \old(x[0]);
  loop assigns x[0..N-1];
  loop variant N-1 - i;
  */
  for(int i =0 ; i<N-1; i++){
     x[i] = x[i+1];
  }
  x[N-1] = temp;
  ret5 = fun(x);
  /*@
  requires \valid(x+(0..N-1));
  requires \valid(x+(0..N-1));
  requires \valid(x+(0..N-1));
  ensures !(ret != ret2 || ret !=ret5);
  */
  return 1;
}
